G = []
V = []
M = []

def find(v):
	for u in G[v]:
		if not V[u]:
			V[u] = True
			if M[u] == -1 or find(M[u]):
				M[u] = v
				return True
	return False
t = int(input())
for _ in range(t):
	(n, k) = list(map(int, input().split()))
	G = [[] for _ in range(n)]
	V = [False for _ in range(n)]
	M = [-1 for _ in range(n)]
	vi = list(map(int, input().split()))
	for x in range(n):
		for y in range(x + 1, n):
			if abs(vi[x] - vi[y]) >= k:
				G[x].append(y)
	res = 0
	for i in range(n):
		V = [False for _ in range(n)]
		if find(i):
			res += 1
	print(n - res)
